def with_camel_case_alias(func):
    """decorator for methods who required a camelcase alias"""
    _camel_case_aliases.add(func.__name__)
    return func


_camel_case_aliases = set()


def build_camel_case_aliases(PyQuery):
    """add camelcase aliases to PyQuery"""
    for alias in _camel_case_aliases:
        parts = list(alias.split('_'))
        name = parts[0] + ''.join([p.title() for p in parts[1:]])
        func = getattr(PyQuery, alias)
        f = types.FunctionType(func.__code__, func.__globals__,
                               name, func.__defaults__)
        f.__doc__ = (
            'Alias for :func:`~pyquery.pyquery.PyQuery.%s`') % func.__name__
        setattr(PyQuery, name, f.__get__(None, PyQuery))


####################################################
# libxml2 HTML parsing backward compatibility layer #
####################################################

# libxml2 2.14 replaced its historical HTML parser by an HTML5 conformant
# one. Three of its behaviours changed the shape of the tree pyquery has
# always exposed (and documented), so they are restored here to keep the
# same document giving the same nodes whatever libxml2 is in use:
#
# * character data at the top level of a document used to open an implied
#   ``<p>`` element,
# * only the HTML 4 named entities were resolved, the HTML 5 only ones were
#   kept as plain text,
# * the content of a ``<textarea>`` was parsed as markup instead of raw text.

# named entities known to the historical libxml2 parser
_legacy_entities = frozenset(name2codepoint) | {'apos'}

# entities only libxml2 >= 2.14 resolves
_html5_entities = frozenset(
    name.rstrip(';') for name in html5) - _legacy_entities

_entity_regex = re.compile(r'&([a-zA-Z][a-zA-Z0-9]*);')

# elements whose content is never parsed as markup nor unescaped
_raw_text_regex = re.compile(r'<(script|style)\b.*?(?:</\1\s*>|\Z)',
                             re.IGNORECASE | re.DOTALL)

_body_regex = re.compile(r'<body[\s/>]', re.IGNORECASE)

# elements which used to close an open <p> element
_block_tags = frozenset((
    'address', 'article', 'aside', 'blockquote', 'center', 'dd', 'details',
    'dialog', 'dir', 'div', 'dl', 'dt', 'fieldset', 'figcaption', 'figure',
    'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'head', 'header',
    'hgroup', 'hr', 'li', 'main', 'menu', 'nav', 'noframes', 'ol', 'p',
    'pre', 'section', 'table', 'ul',
))


def _escape_html5_entities(html):
    """keep the entities libxml2 used to ignore as plain text"""
    def repl(match):
        if match.group(1) in _html5_entities:
            return '&amp;%s;' % match.group(1)
        return match.group(0)

    result = []
    position = 0
    # entities are not resolved in raw text elements
    for raw_text in _raw_text_regex.finditer(html):
        result.append(_entity_regex.sub(repl, html[position:raw_text.start()]))
        result.append(raw_text.group(0))
        position = raw_text.end()
    result.append(_entity_regex.sub(repl, html[position:]))
    return ''.join(result)


def _restore_textarea_markup(element):
    """parse the raw content of the textareas as markup"""
    for tag in element.iter('textarea'):
        text = tag.text
        if not text or '<' not in text or len(tag):
            continue
        try:
            root = lxml.html.fragment_fromstring(text, create_parent='div')
        except Exception:
            continue
        children = root.getchildren()
        if not children:
            continue
        tag.text = root.text
        tag.extend(children)


def _wrap_leading_text(container):
    """move the leading character data of container in a <p> element"""
    text = container.text
    if not text or not text.strip():
        return None
    paragraph = container.makeelement('p')
    paragraph.text = text
    container.text = None
    for child in list(container):
        tag = child.tag
        if isinstance(tag, basestring) and tag.lower() in _block_tags:
            # the paragraph used to be closed by such elements
            break
        # removing the child keeps its tail attached to it
        container.remove(child)
        paragraph.append(child)
    container.insert(0, paragraph)
    return paragraph


def _restore_implied_paragraph(element):
    """open an implied <p> element for top level character data"""
    if element.tag == 'html':
        body = element.find('body')
        if body is not None:
            _wrap_leading_text(body)
        return element
    parent = element.getparent()
    if (element.tag not in ('span', 'div') or
            parent is None or parent.tag != 'html'):
        # not one of the containers lxml.html builds for html fragments
        return element
    paragraph = _wrap_leading_text(element)
    if paragraph is None:
        return element
    if len(element) == 1 and not (paragraph.tail or '').strip():
        # lxml.html would have returned the paragraph itself
        element.tag = 'body'
        return paragraph
    # the container now holds a block level element
    element.tag = 'div'
    return element


def _html_parser(meth):
    """``lxml.html`` parser with the historical behaviours restored"""
    parse = getattr(lxml.html, meth)

    def parser(context):
        # bytes may carry an encoding declaration. leave them alone
        source = context if isinstance(context, str) else None
        if source is not None:
            context = _escape_html5_entities(source)
        result = parse(context)
        if isinstance(result, etree._ElementTree):
            elements = [result.getroot()]
        elif isinstance(result, list):
            elements = result
        elif result is None:
            elements = []
        else:
            elements = [result]
        elements = [e for e in elements if e is not None]
        for element in elements:
            if not isinstance(element, basestring):
                _restore_textarea_markup(element)
        if source is None or _body_regex.search(source):
            return elements
        return [element if isinstance(element, basestring)
                else _restore_implied_paragraph(element)
                for element in elements]

    return parser


def fromstring(context, parser=None, custom_parser=None):
    """use html parser if we don't have clean xml
    """
    if hasattr(context, 'read') and hasattr(context.read, '__call__'):
        meth = 'parse'
    else:
        meth = 'fromstring'
    if custom_parser is None:
        if parser is None:
            try:
                result = getattr(etree, meth)(context)
            except etree.XMLSyntaxError:
                if hasattr(context, 'seek'):
                    context.seek(0)
                return _html_parser(meth)(context)
            if isinstance(result, etree._ElementTree):
                return [result.getroot()]
            else:
                return [result]
        elif parser == 'xml':
            custom_parser = getattr(etree, meth)
        elif parser == 'html':
            custom_parser = _html_parser(meth)
        elif parser == 'html5':
            from lxml.html import html5parser
            custom_parser = getattr(html5parser, meth)
        elif parser == 'soup':
            from lxml.html import soupparser
            custom_parser = getattr(soupparser, meth)
        elif parser == 'html_fragments':
            custom_parser = _html_parser('fragments_fromstring')
        else:
            raise ValueError('No such parser: "%s"' % parser)

    result = custom_parser(context)
    if isinstance(result, list):
        return result
    elif isinstance(result, etree._ElementTree):
        return [result.getroot()]
    elif result is not None:
        return [result]
    else:
        return []


def callback(func, *args):
    return func(*args[:func.__code__.co_argcount])


class NoDefault(object):
    def __repr__(self):
        """clean representation in Sphinx"""
        return '<NoDefault>'


no_default = NoDefault()
del NoDefault


class FlexibleElement(object):
    """property to allow a flexible api"""
    def __init__(self, pget, pset=no_default, pdel=no_default):
        self.pget = pget
        self.pset = pset
        self.pdel = pdel

    def __get__(self, instance, klass):
        class _element(object):
            """real element to support set/get/del attr and item and js call
            style"""
            def __call__(prop, *args, **kwargs):
                return self.pget(instance, *args, **kwargs)
            __getattr__ = __getitem__ = __setattr__ = __setitem__ = __call__

            def __delitem__(prop, name):
                if self.pdel is not no_default:
                    return self.pdel(instance, name)
                else:
                    raise NotImplementedError()
            __delattr__ = __delitem__

            def __repr__(prop):
                return '<flexible_element %s>' % self.pget.__name__
        return _element()

    def __set__(self, instance, value):
        if self.pset is not no_default:
            self.pset(instance, value)
        else:
            raise NotImplementedError()


