def prev_all(self, selector=None):
    """
    >>> h = '<span><p class="hello">Hi</p><p>Bye</p><img scr=""/></span>'
    >>> d = PyQuery(h)
    >>> d('p:last').prev_all()
    [<p.hello>]
    >>> d('p:last').prevAll()
    [<p.hello>]
    """
    return self._filter_only(selector, self._prev_all(), reverse=True)

def siblings(self, selector=None):
    """
     >>> h = '<span><p class="hello">Hi</p><p>Bye</p><img scr=""/></span>'
     >>> d = PyQuery(h)
